S=/private/tmp/claude-501/-Users-nasarissa-verify-blind-runs-run3-todo-app-4/043f7cd3-eed0-4f2d-a816-f8e31d364ca3/scratchpad; mkdir -p $S; cat > $S/sim.js <<'EOF'
const fs=require('fs'),vm=require('vm'),dir=process.argv[2];
const html=fs.readFileSync(dir+'/index.html','utf8');
const ids=[...html.matchAll(/id="([^"]+)"/g)].map(m=>m[1]);
const els={};ids.forEach(i=>els[i]={children:[],appendChild(c){this.children.push(c)}});
const document={getElementById:i=>els[i]||null,createElement:t=>({tag:t,textContent:''})};
const ctx=vm.createContext({document});
try{ for(const s of [...html.matchAll(/src="([^"]+)"/g)].map(m=>m[1])) vm.runInContext(fs.readFileSync(dir+'/'+s,'utf8'),ctx,{filename:s});
}catch(e){console.log('ERROR:',e.message)}
for(const i in els) console.log('#'+i,'->',els[i].children.map(c=>c.textContent));
EOF
node $S/sim.js .; echo "--- with id fixed (in a copy) ---"; rm -rf $S/fixed; mkdir $S/fixed; cp *.js $S/fixed; sed 's/id="todos"/id="todo-list"/' index.html > $S/fixed/index.html; node $S/sim.js $S/fixed

